            var list = new List<KnowledgeItem>(320);

            list.Add(new KnowledgeItem("KB001", "建筑", "疏散门开启方向错误", "疏散门未向疏散方向开启，公共场所及人数超过60人的房间疏散门应向疏散方向开启。", "GB 55037-2022 7.4.1"));
            list.Add(new KnowledgeItem("KB002", "建筑", "楼梯防护栏杆高度不足", "临空构件防护栏杆净高不应低于1.10m，栏杆间距必须满足防攀爬及竖向净距不大于0.11m要求。", "GB 55031-2022 5.3.1"));
            list.Add(new KnowledgeItem("KB003", "建筑", "无障碍坡道坡度超标", "室内外无障碍坡道坡度超过设计限值，坡道净宽度、两端平坡段长度及双侧扶手高度需复核。", "GB 50763-2012 3.4.3"));
            list.Add(new KnowledgeItem("KB004", "建筑", "管道井检修门耐火等级不足", "电缆井、管道井检修门耐火极限不得低于丙级，门表与平面图耐火等级标注应保持一致。", "GB 55037-2022 6.3.3"));
            list.Add(new KnowledgeItem("KB005", "建筑", "主要功能空间净高不足", "卧室、起居室室内净高不应低于2.50m，局部净高不应低于2.10m且面积不应大于室内使用面积的三分之一。", "GB 55031-2022 5.1.2"));
            list.Add(new KnowledgeItem("KB006", "建筑", "上下层开口防火间距不足", "建筑外墙上下层开口之间未设置高度不低于1.2m的实体墙或耐火完整性不低于1.00h的防火玻璃墙。", "GB 55037-2022 4.3.4"));
            list.Add(new KnowledgeItem("KB007", "建筑", "疏散走道净宽度不足", "人员密集的公共场所、观众厅的疏散走道、疏散楼梯间及其前室的门的净宽度不应小于1.40m。", "GB 55037-2022 7.1.4"));
            list.Add(new KnowledgeItem("KB008", "建筑", "安全出口数量不足", "建筑每个防火分区或一个防火分区的每个楼层，其安全出口数量应经计算确定，且不应少于2个。", "GB 55037-2022 7.1.1"));
            list.Add(new KnowledgeItem("KB009", "建筑", "地下室防火分区超标", "地下或半地下建筑每个防火分区的最大允许建筑面积不应大于500㎡，设置自喷时可增加一倍至1000㎡。", "GB 55037-2022 2.1.2"));
            list.Add(new KnowledgeItem("KB010", "建筑", "楼梯踏步宽度和高度不合规", "公共楼梯踏步最小宽度不应小于0.28m，最大高度不应大于0.16m，且同一楼梯段踏步高宽应一致。", "GB 55031-2022 5.3.2"));
            list.Add(new KnowledgeItem("KB011", "建筑", "住宅窗台防护高度不足", "低窗台、凸窗等临空窗台防护高度自窗台面起计算不应低于0.90m，可开启扇净高不足处应设防护栏杆。", "GB 50096-2011 5.8.1"));
            list.Add(new KnowledgeItem("KB012", "建筑", "楼梯间前室使用面积偏小", "防烟楼梯间前室使用面积不应小于6.0㎡，与消防电梯合用前室使用面积不应小于10.0㎡。", "GB 55037-2022 7.1.8"));
            list.Add(new KnowledgeItem("KB013", "建筑", "避难走道设置不合规", "避难走道防火隔墙耐火极限不应低于3.00h，走道直通地面的出口不应少于2个且应设置防烟设施。", "GB 55037-2022 7.2.3"));
            list.Add(new KnowledgeItem("KB014", "建筑", "防火卷帘耐火极限未注明", "防火卷帘耐火极限不应低于3.00h，其跨度、背火面温升判定条件及防烟性能应符合通用规范要求。", "GB 55037-2022 6.4.1"));
            list.Add(new KnowledgeItem("KB015", "建筑", "屋面防水等级与道数不符", "屋面防水工程设计工作年限不应低于20年，一级防水应采用不少于两道防水设防要求。", "GB 55030-2022 3.1.2"));
            list.Add(new KnowledgeItem("KB016", "建筑", "地下室防水设防等级不足", "地下工程防水设防要求应满足抗渗防潮，地下人员长期停留场所防水等级应为一级且不得渗水。", "GB 55030-2022 4.1.2"));
            list.Add(new KnowledgeItem("KB017", "建筑", "无障碍出入口轮椅坡道缺失", "公共建筑及住宅主出入口存在高差处必须设置无障碍坡道和轮椅通行通道及扶手设施。", "GB 55019-2021 2.1.2"));
            list.Add(new KnowledgeItem("KB018", "建筑", "无障碍卫生间回转空间不足", "无障碍单人卫生间内应设直径不小于1.50m的轮椅回转空间，坐便器、洗手盆及安全抓杆尺寸应符合要求。", "GB 55019-2021 3.2.1"));
            list.Add(new KnowledgeItem("KB019", "建筑", "无障碍电梯轿厢净尺寸不足", "无障碍电梯轿厢门净宽度不应小于0.80m，轿厢深度不应小于1.40m，宽度不应小于1.10m。", "GB 55019-2021 3.3.2"));
            list.Add(new KnowledgeItem("KB020", "建筑", "室内环境甲醛与TVOC未控", "民用建筑室内装饰装修设计应进行室内空气质量预评价，控制氡、游离甲醛、苯及TVOC释放总量。", "GB 55016-2021 3.1.1"));
            list.Add(new KnowledgeItem("KB021", "建筑", "建筑采光有效采光面积偏小", "居住建筑起居室、卧室采光窗地面积比不应低于1/7，采光有效进深比应满足采光系数标准。", "GB 55016-2021 4.1.1"));
            list.Add(new KnowledgeItem("KB022", "建筑", "住宅分户墙隔声性能不达标", "卧室、起居室分户墙及楼板空气声计权隔声量+粉红噪声谱修正量不应小于45dB，撞击声不应大于65dB。", "GB 55016-2021 5.1.2"));
            list.Add(new KnowledgeItem("KB023", "建筑", "建筑幕墙防火封堵未详", "建筑幕墙与每层楼板、隔墙处的缝隙应采用防火封堵材料在耐火极限范围内严密封堵。", "GB 55037-2022 6.5.2"));
            list.Add(new KnowledgeItem("KB024", "建筑", "消防车道转弯半径不足", "消防车道转弯半径应满足消防车转弯要求，普通消防车不应小于9m，登高车不应小于12m。", "GB 55037-2022 3.4.2"));
            list.Add(new KnowledgeItem("KB025", "建筑", "消防车登高操作场地受阻", "消防车登高操作场地靠建筑外墙一侧不应种植高大树木、架空管线或设置妨碍登高操作的障碍物。", "GB 55037-2022 3.4.5"));
            list.Add(new KnowledgeItem("KB026", "建筑", "电梯井道与居室紧邻布置", "电梯井道及电梯机房不应紧邻卧室布置，受条件限制紧邻时应采取双层墙及隔振降噪有效措施。", "GB 50096-2011 5.4.4"));
            list.Add(new KnowledgeItem("KB027", "建筑", "厨房卫生间排气道串味隐患", "厨房、卫生间共用排气道系统应具备防倒灌及防火止回阀构造，排气口出屋面高度应合规。", "GB 55031-2022 6.3.2"));
            list.Add(new KnowledgeItem("KB028", "建筑", "屋面雨水天沟及溢流口缺失", "屋面防水系统应设溢流设施，溢流口底标高应高于天沟最高水面并低于外墙泛水上口。", "GB 55030-2022 3.3.4"));
            list.Add(new KnowledgeItem("KB029", "建筑", "自行车及电动车停放防火间距", "电动自行车集中停放及充电场所应独立设置，紧邻建筑时应采用防火隔墙与安全出口保持安全间距。", "GB 55037-2022 2.2.4"));
            list.Add(new KnowledgeItem("KB030", "建筑", "商业步行街防火分区隔离", "有顶商业步行街两侧建筑耐火等级不应低于二级，步行街端部及自然排烟开口面积需满足规范。", "GB 55037-2022 2.1.8"));
            list.Add(new KnowledgeItem("KB031", "建筑", "疏散距离超规范最大允许值", "房间内任一点至直通疏散走道的疏散门直线距离超过规范限值，大空间展厅布置需优化疏散动线。", "GB 55037-2022 7.1.6"));
            list.Add(new KnowledgeItem("KB032", "建筑", "袋形走道尽端疏散距离过长", "高层病房楼、托儿所袋形走道两侧或尽端的疏散门至最近安全出口的直线距离超规范限值要求。", "GB 55037-2022 7.1.7"));
            list.Add(new KnowledgeItem("KB033", "建筑", "托儿所幼儿园生活用房楼层过高", "托儿所、幼儿园儿童生活用房不应设置在四层及以上，三层仅限布置大班儿童活动室且应设独立疏散楼梯。", "GB 55031-2022 3.2.3"));
            list.Add(new KnowledgeItem("KB034", "建筑", "儿童活动场所活动栏杆易攀爬", "托儿所、中小学校及儿童活动场所防护栏杆必须采用防止攀登构造，竖向垂直杆件净间距不应大于0.09m。", "GB 55031-2022 5.3.3"));
            list.Add(new KnowledgeItem("KB035", "建筑", "中小学教学楼走道宽度不足", "中小学校教学楼普通教室走道净宽度，外廊单侧走道不应小于1.80m，内廊双侧走道不应小于2.40m。", "GB 50099-2011 6.2.2"));
            list.Add(new KnowledgeItem("KB036", "建筑", "汽车库人员安全出口数量不足", "汽车库每个防火分区人员安全出口不应少于2个，Ⅳ类汽车库和设置双车道且停车数少于50辆可设1个。", "GB 50067-2014 6.0.1"));
            list.Add(new KnowledgeItem("KB037", "建筑", "汽车库汽车疏散坡道净宽度不足", "小型汽车单车道微型车疏散坡道净宽度不应小于3.5m，双车道净宽度不应小于5.5m，净高不应小于2.2m。", "JGJ 100-2015 4.2.4"));
            list.Add(new KnowledgeItem("KB038", "建筑", "变形缝处防火门跨缝设置", "防火门不应跨越变形缝安装，必须设在变形缝附近时应安装在楼层较多或火灾危险性较小的一侧。", "GB 55037-2022 6.4.3"));
            list.Add(new KnowledgeItem("KB039", "建筑", "外保温材料燃烧性能不符", "人员密集场所、高层建筑外墙外保温材料燃烧性能应为A级，防护层厚度及水平防火隔离带构造应注明。", "GB 55037-2022 6.6.1"));
            list.Add(new KnowledgeItem("KB040", "建筑", "采光顶与中庭玻璃非安全玻璃", "屋顶玻璃、中庭天棚及临空高度超5m的玻璃采光顶必须采用夹层玻璃或具有防坠落防冲击安全玻璃。", "JGJ 102-2003 7.1.2"));
            list.Add(new KnowledgeItem("KB041", "建筑", "中庭防火隔断耐火极限不足", "贯通多个楼层的室内中庭四周与周围连通空间未设置耐火极限不低于1.00h的防火隔墙或防火卷帘。", "GB 55037-2022 2.1.7"));
            list.Add(new KnowledgeItem("KB042", "建筑", "地下车库充电桩防火单元超标", "地下汽车库电动汽车充电设施防火单元内停车数量超过最大允许限值，防火隔墙与独立疏散出口需复核。", "GB 50067-2014 5.1.1"));
            list.Add(new KnowledgeItem("KB043", "建筑", "超高层建筑避难层间距超标", "建筑高度大于100m的公共建筑，第一个避难层楼地面至灭火救援场地高度不应大于50m，相邻避难层不大于50m。", "GB 55037-2022 7.3.1"));
            list.Add(new KnowledgeItem("KB044", "建筑", "屋面女儿墙及挑檐泛水高度不足", "屋面女儿墙和挑檐防水层收头处泛水高度不应小于250mm，收头凹槽及金属压条固定密封节点缺失。", "GB 55030-2022 3.3.1"));
            list.Add(new KnowledgeItem("KB045", "建筑", "外窗淋水及气密性能等级未注", "外门窗物理三性（抗风压性能、气密性能、水密性能）设计指标未在门窗节能表及设计总说明中详列。", "GB 55015-2021 3.2.3"));
            list.Add(new KnowledgeItem("KB046", "建筑", "自动扶梯周边防跌落防护缺失", "自动扶梯、自动人行道与楼板交界外侧空隙大于规范限值处未设防跌落护栏或防夹防跌挡板安全设施。", "GB 55031-2022 5.3.4"));
            list.Add(new KnowledgeItem("KB047", "建筑", "公共卫生间男女厕位比例失调", "商场、医院、交通枢纽等公共建筑男女厕位比例不合规，女厕位数量未满足规范1:1.5至1:2配比标准。", "GB 50352-2019 6.6.1"));
            list.Add(new KnowledgeItem("KB048", "建筑", "锅炉房变配电室泄爆面积不足", "甲乙类厂房、燃气燃油锅炉房未设置轻质屋盖或泄压门窗，泄压面积计算比值未满足防爆设计要求。", "GB 55037-2022 4.1.6"));
            list.Add(new KnowledgeItem("KB049", "建筑", "屋面设备平台减振隔声措施未详", "设置于屋顶或楼层上方的冷却塔、热泵机组未注明结构浮筑隔振降噪和吸音屏障具体构造技术参数。", "GB 55016-2021 5.2.3"));
            list.Add(new KnowledgeItem("KB050", "建筑", "消防救援窗外观标志与尺寸不足", "厂房、仓库、公共建筑外墙设置的供消防救援人员进入的窗口，净尺寸不应小于1.0m×1.0m且应设易识别标识。", "GB 55037-2022 3.4.6"));
            list.Add(new KnowledgeItem("KB051", "建筑", "公共走道排烟口临近安全出口", "机械排烟系统排烟口与最近安全出口疏散门相邻水平距离小于1.5m，烟气易涌入楼梯间危害疏散安全。", "GB 51251-2017 4.4.12"));
            list.Add(new KnowledgeItem("KB052", "建筑", "地下室采光井下部防倒灌措施", "半地下室、地下室下沉式采光井及出入口未设截水沟、集水坑和自动强排水泵设施，存在暴雨倒灌隐患。", "GB 55030-2022 4.2.3"));
            list.Add(new KnowledgeItem("KB053", "结构", "梁柱节点核心区配筋过密", "主次梁及梁柱交接核心区配筋密集，钢筋净间距不足导致混凝土浇筑振捣通道受阻。", "GB 55008-2021 4.4.6"));
            list.Add(new KnowledgeItem("KB054", "结构", "混凝土构件保护层厚度偏小", "受力钢筋混凝土保护层厚度未满足设计环境类别下的耐久性最小厚度限值要求。", "GB 55008-2021 4.2.1"));
            list.Add(new KnowledgeItem("KB055", "结构", "构件抗震构造措施不满足", "框架柱箍筋加密区最小长度、箍筋肢距及配箍特征值不满足抗震设防等级要求。", "GB 55002-2021 4.1.2"));
            list.Add(new KnowledgeItem("KB056", "结构", "剪力墙边缘构件配筋不足", "约束边缘构件或构造边缘构件配箍范围、纵向钢筋配筋率未达规范限值。", "GB 50010-2010(2015版) 11.7.14"));
            list.Add(new KnowledgeItem("KB057", "结构", "结构扭转不规则位移比超限", "在考虑偶然偏心影响规定水平力作用下，楼层竖向构件最大水平位移大于平均位移的1.2倍未控。", "GB 55002-2021 3.2.2"));
            list.Add(new KnowledgeItem("KB058", "结构", "楼层刚度突变产生软弱层", "本层侧向刚度小于相邻上一层的70%或小于其上相邻三个楼层平均刚度的80%，未采取加强措施。", "GB 55002-2021 3.2.4"));
            list.Add(new KnowledgeItem("KB059", "结构", "框架柱轴压比超出限值", "框架柱轴压比超出抗震等级对应规范最大允许限值，柱截面尺寸或混凝土强度等级偏低。", "GB 55008-2021 4.4.4"));
            list.Add(new KnowledgeItem("KB060", "结构", "梁端纵向受拉钢筋配筋率偏高", "抗震框架梁梁端截面受拉钢筋配筋率大于2.5%，梁端底面与顶面配筋比值小于规范强制指标。", "GB 55008-2021 4.4.2"));
            list.Add(new KnowledgeItem("KB061", "结构", "地下室外墙抗裂及保护层不足", "地下室外墙受土水压力作用配筋计算裂缝宽度超标，迎水面受力筋保护层厚度不应小于50mm。", "GB 55008-2021 4.2.3"));
            list.Add(new KnowledgeItem("KB062", "结构", "楼面活荷载取值偏小", "结构荷载计算书所取商业、机房、汽车库等房间楼面活荷载未满足工程结构通用规范强制底线。", "GB 55001-2021 4.2.1"));
            list.Add(new KnowledgeItem("KB063", "结构", "屋面雪荷载及风荷载基准期不符", "结构抗力计算所采用基本风压和基本雪压基准期低于设计基准期50年重现期要求。", "GB 55001-2021 4.3.1"));
            list.Add(new KnowledgeItem("KB064", "结构", "地基承载力特征值未经检测复核", "设计采用的地基承载力特征值高于现场原位测试或载荷试验标准，需设计工况实地校验。", "GB 55003-2021 3.2.1"));
            list.Add(new KnowledgeItem("KB065", "结构", "基础抗浮验算安全系数不足", "地下室在最高抗浮设防水位下的抗浮稳定性验算安全系数小于规范强制要求的1.05限值。", "GB 55003-2021 3.1.4"));
            list.Add(new KnowledgeItem("KB066", "结构", "预制桩桩端持力层深度不足", "预制管桩桩尖进入坚硬持力层深度或贯入度控制指标未满足单桩承载力和沉降控制要求。", "GB 55003-2021 5.2.2"));
            list.Add(new KnowledgeItem("KB067", "结构", "混凝土结构伸缩缝间距超标", "现浇钢筋混凝土框架结构伸缩缝最大间距超出规范限值，未采取有效减少温度应力的构造措施。", "GB 50010-2010(2015版) 8.1.1"));
            list.Add(new KnowledgeItem("KB068", "结构", "砌体结构抗震横墙间距过大", "多层砌体房屋抗震横墙最大间距超出抗震规范限定值，房屋刚度与整体稳定性不足。", "GB 55007-2021 4.1.3"));
            list.Add(new KnowledgeItem("KB069", "结构", "砌体构造柱圈梁设置不完整", "多层砌体结构外墙四角、错层处未按规定设置构造柱与现浇圈梁，结构抗震延性不足。", "GB 55007-2021 4.2.1"));
            list.Add(new KnowledgeItem("KB070", "结构", "钢结构高强螺栓抗滑移系数未注", "钢构件摩擦型高强度螺栓连接接头处构件接触面喷砂处理及抗滑移系数设计值图纸未标注。", "GB 55006-2021 4.2.2"));
            list.Add(new KnowledgeItem("KB071", "结构", "钢结构焊缝质量等级不明确", "钢框架梁柱对接全熔透焊缝质量等级未注明一级或二级，图纸未明确无损探伤检测要求。", "GB 55006-2021 4.2.5"));
            list.Add(new KnowledgeItem("KB072", "结构", "钢构件长细比与板件宽厚比超标", "受压钢构件长细比超限，受弯及压弯构件腹板、翼缘宽厚比未满足局部稳定限值要求。", "GB 50017-2017 3.5.1"));
            list.Add(new KnowledgeItem("KB073", "结构", "钢结构防火涂料耐火极限未注", "钢柱、钢梁、钢屋架耐火等级对应防火保护层厚度及防火涂料型号未在设计总说明中详列。", "GB 55037-2022 4.1.2"));
            list.Add(new KnowledgeItem("KB074", "结构", "地下室顶板作为上部嵌固端刚度不足", "地下室顶板作为结构嵌固端时，楼板厚度不应小于180mm，侧向刚度比不应小于上部相邻层的2倍。", "GB 50011-2010(2016版) 6.1.14"));
            list.Add(new KnowledgeItem("KB075", "结构", "抗震等级确定错误", "建筑抗震设防类别与结构高度对应抗震等级确定偏低，关键构件抗震调整系数采用错误。", "GB 55002-2021 4.1.1"));
            list.Add(new KnowledgeItem("KB076", "结构", "框架主次梁交接处附加横向钢筋缺失", "主次梁交接处次梁集中荷载作用部位未配置附加吊筋或附加箍筋，受剪承载力不足。", "GB 50010-2010(2015版) 9.2.11"));
            list.Add(new KnowledgeItem("KB077", "结构", "悬挑构件抗倾覆验算不足", "大跨度雨棚、悬挑阳台等悬挑构件抗倾覆安全系数不足，未考虑竖向地震及活荷载不利布置。", "GB 55001-2021 3.2.5"));
            list.Add(new KnowledgeItem("KB078", "结构", "雨棚挑梁抗裂及挠度超标", "悬臂构件按荷载准永久组合计算的挠度及裂缝宽度超出允许限值，构件刚度偏软。", "GB 50010-2010(2015版) 3.4.3"));
            list.Add(new KnowledgeItem("KB079", "结构", "板角暗梁及放射加强筋缺失", "建筑物外角跨双向板未在板角布置双向面筋或辐射状抗裂加强钢筋，板角易产生45度斜裂缝。", "GB 50010-2010(2015版) 9.1.10"));
            list.Add(new KnowledgeItem("KB080", "结构", "楼梯梯段板受力钢筋锚固长度不足", "楼梯梯段板端部纵向受拉钢筋锚入支座梁内的水平和垂直弯折锚固长度未达到受拉锚固要求。", "GB 55008-2021 4.3.2"));
            list.Add(new KnowledgeItem("KB081", "结构", "结构转换层托柱梁截面尺寸偏小", "部分框支剪力墙结构转换梁截面高度不宜小于跨度的1/6，且转换梁中柱核心区抗剪截面不满足要求。", "JGJ 3-2010 10.2.7"));
            list.Add(new KnowledgeItem("KB082", "结构", "转换柱配筋率与体积配箍率偏低", "托柱转换柱截面全高范围内箍筋未全高加密，体积配箍率及纵向钢筋最小总配筋率未达规范要求。", "JGJ 3-2010 10.2.11"));
            list.Add(new KnowledgeItem("KB083", "结构", "剪力墙底部加强部位高度确定有误", "剪力墙底部加强部位高度未满足墙肢总高度的1/10且不小于底部两层的高度要求。", "GB 50011-2010(2016版) 6.1.10"));
            list.Add(new KnowledgeItem("KB084", "结构", "短肢剪力墙抗震措施不足", "结构中短肢剪力墙截面面积占比较高，抗震等级未按规定提高一级且轴压比控制偏宽。", "JGJ 3-2010 7.1.8"));
            list.Add(new KnowledgeItem("KB085", "结构", "大跨度框架梁挠度验算未满足", "跨度大于9m的框架大梁按短期效应组合考虑长期挠度影响后，挠度超出跨度1/300规范限值。", "GB 50010-2010(2015版) 3.4.3"));
            list.Add(new KnowledgeItem("KB086", "结构", "现浇楼板开洞削弱未设补偿措施", "设备管井导致楼板开洞尺寸大于该板块尺寸30%时，未在洞口周边配置边梁或附加补强钢筋。", "GB 50010-2010(2015版) 9.1.11"));
            list.Add(new KnowledgeItem("KB087", "结构", "钢筋焊接与机械连接接头百分率超标", "受拉钢筋绑扎接头面积百分率大于25%或机械连接接头面积百分率大于50%，不符合接头受拉区规范要求。", "GB 55008-2021 4.3.4"));
            list.Add(new KnowledgeItem("KB088", "结构", "地基基础沉降差超允许值", "高低层连体建筑或主附楼由于荷载差异导致地基沉降差超出规范限值，未设沉降后浇带或沉降缝。", "GB 55003-2021 3.2.4"));
            list.Add(new KnowledgeItem("KB089", "结构", "基坑支护结构稳定性计算缺失", "深基坑支护桩锚杆嵌入深度及整体抗滑移、抗隆起稳定性验算未满足基坑安全等级要求。", "GB 55003-2021 6.1.2"));
            list.Add(new KnowledgeItem("KB090", "结构", "桩基础承台抗冲切抗剪切不足", "多桩承台截面有效高度偏小，承台受柱冲切及受角桩冲切承载力未满足计算复核。", "GB 50007-2011 8.5.17"));
            list.Add(new KnowledgeItem("KB091", "结构", "后浇带钢筋断开及防渗处理未详", "超长地下室温度后浇带及沉降后浇带钢筋配置、封堵材料强度等级及超前止水钢板构造未详。", "GB 55030-2022 4.2.1"));
            list.Add(new KnowledgeItem("KB092", "结构", "钢筋混凝土受弯构件最小配筋率", "受拉钢筋截面面积与全截面面积比值低于0.20%与45ft/fy%二者较大者，构件存在脆性破坏风险。", "GB 55008-2021 4.1.3"));
            list.Add(new KnowledgeItem("KB093", "结构", "型钢混凝土组合构件剪结连接件缺失", "型钢混凝土柱及梁内型钢与混凝土交接面未按设计剪力要求设置足够数量圆柱头焊钉连接件。", "GB 55004-2021 4.2.3"));
            list.Add(new KnowledgeItem("KB094", "结构", "预应力构件张拉控制应力超限", "后张法预应力钢绞线张拉控制应力超过材料抗拉强度标准值的0.75倍，存在断丝或应力腐蚀风险。", "GB 55008-2021 4.3.7"));
            list.Add(new KnowledgeItem("KB095", "结构", "轻集料及加气混凝土砌块强度偏低", "框架填充墙采用加气混凝土砌块强度等级低于A3.5，砂浆强度低于M5.0，不满足耐久抗裂要求。", "GB 55007-2021 3.1.2"));
            list.Add(new KnowledgeItem("KB096", "结构", "填充墙与主体结构拉结筋未详", "非承重填充墙与主体柱墙交接处未设置2Φ6@500拉结钢筋，且锚入墙体长度未满足规范要求。", "GB 50011-2010(2016版) 13.3.3"));
            list.Add(new KnowledgeItem("KB097", "结构", "顶层女儿墙抗震抗倾覆配筋缺失", "屋顶砌体女儿墙高度超过0.5m未设钢筋混凝土构造柱和压顶梁，存在地震脱落砸伤隐患。", "GB 50011-2010(2016版) 13.3.2"));
            list.Add(new KnowledgeItem("KB098", "结构", "钢结构柱脚锚栓抗剪验算不足", "刚接柱脚底板与基础顶面抗剪摩擦力不足，未在柱底板底面设置抗剪键槽或型钢抗剪件。", "GB 50017-2017 12.7.4"));
            list.Add(new KnowledgeItem("KB099", "结构", "网架网壳结构支座温度应变受阻", "大跨度空间网架橡胶支座未预留双向滑移或释放温度变形转动量，导致下部支撑柱顶推力超标。", "GB 55006-2021 5.3.1"));
            list.Add(new KnowledgeItem("KB100", "结构", "装配式混凝土构件灌浆套筒间距", "装配式预制剪力墙竖向钢筋采用套筒灌浆连接时，套筒间距过小无法保证灌浆饱满度及密实性。", "GB 55008-2021 4.3.5"));
            list.Add(new KnowledgeItem("KB101", "结构", "预制叠合板后浇层厚度不足", "预制预应力混凝土叠合板后浇混凝土面层厚度小于60mm，未能满足作为刚性楼盖整体受力要求。", "GB 55008-2021 4.4.7"));
            list.Add(new KnowledgeItem("KB102", "结构", "结构抗震性能设计目标不明确", "复杂高层或超限高层结构未在说明中明确针对不同水准地震作用下的构件抗震性能目标与验算指标。", "GB 55002-2021 3.3.1"));
            list.Add(new KnowledgeItem("KB103", "结构", "穿层柱及斜柱未按特一级抗震构造", "大空间建筑穿层柱其计算长度过大，设计未按穿层构件考虑轴压比折减及箍筋全高加密。", "JGJ 3-2010 10.5.2"));
            list.Add(new KnowledgeItem("KB104", "结构", "地下室坡道外侧悬臂挡土墙受弯验算", "车库出入口坡道露天挡土墙抗滑移验算及根部受弯主筋锚固深度未满足挡土防冻胀要求。", "GB 55003-2021 6.2.3"));
            list.Add(new KnowledgeItem("KB105", "给排水", "消火栓箱影响有效疏散宽度", "消火栓箱明装凸出墙面，占用公共走道有效疏散宽度，建议改为暗装或半暗装。", "GB 50974-2014 7.4.7"));
            list.Add(new KnowledgeItem("KB106", "给排水", "生活饮用水防倒流污染隔离", "生活饮用水管道直接与非生活用水管道连接，未设置倒流防止器或空气间隙隔断。", "GB 55020-2021 3.1.5"));
            list.Add(new KnowledgeItem("KB107", "给排水", "高位消防水箱有效容积不足", "高位消防水箱有效储水容积或最低有效水位报警设置不满足建筑类别计算要求。", "GB 50974-2014 5.2.6"));
            list.Add(new KnowledgeItem("KB108", "给排水", "排水通气立管出屋面高度不足", "上人屋面通气管高出屋面未达2.0m，或通气管出口与门窗距离小于4.0m。", "GB 50015-2019 4.3.4"));
            list.Add(new KnowledgeItem("KB109", "给排水", "消防水泵吸水管偏心异径管方向装反", "消防水泵吸水管采用变径连接时应采用管顶平接的偏心异径管，防止管内形成气囊阻碍吸水。", "GB 50974-2014 5.1.13"));
            list.Add(new KnowledgeItem("KB110", "给排水", "室内消火栓布置间距超标", "高层公共建筑消火栓布置间距大于30.0m，未保证两股水枪充实水柱同时到达室内任何部位。", "GB 50974-2014 7.4.6"));
            list.Add(new KnowledgeItem("KB111", "给排水", "消防水池有效容积及补水时间不足", "消防水池有效容积未扣除死水层，补水管进水流速与连续补水补满时间超标。", "GB 50974-2014 4.3.4"));
            list.Add(new KnowledgeItem("KB112", "给排水", "湿式报警阀组控制喷头数量超标", "一个湿式报警阀组控制的喷头数，严重危险级和中危险级不宜超过800只，轻危险级不宜超过1000只。", "GB 50084-2017 6.2.3"));
            list.Add(new KnowledgeItem("KB113", "给排水", "地下车库喷头选型及布置错误", "地下车库易受碰撞场所喷头未选用防护罩型，喷头溅水盘与顶板梁底距离不满足喷水分布要求。", "GB 50084-2017 7.1.3"));
            list.Add(new KnowledgeItem("KB114", "给排水", "自动喷水灭火末端试水装置缺失", "每个报警阀组控制的最不利点喷头处未设置末端试水装置，其他楼层未设试水阀及排水设施。", "GB 50084-2017 6.5.1"));
            list.Add(new KnowledgeItem("KB115", "给排水", "室外消火栓与水泵接合器距离不当", "水泵接合器处15m至40m范围内未布置室外消火栓或消防水池取水口，不利于消防车吸水加压。", "GB 50974-2014 5.4.7"));
            list.Add(new KnowledgeItem("KB116", "给排水", "消防水泵出水管未设压力表及泄压阀", "消防水泵出水干管上未设置压力表、低阻力倒流防止器及用于试验的放水测试阀门及回流管。", "GB 50974-2014 5.1.11"));
            list.Add(new KnowledgeItem("KB117", "给排水", "生活给水管道超压未设减压阀", "用水点处供水静水压力大于0.35MPa未设减压设施，管网存在水锤冲击、振动及管道破裂风险。", "GB 55020-2021 3.2.3"));
            list.Add(new KnowledgeItem("KB118", "给排水", "卫生洁具未采用节水型配件", "公共建筑生活用水器具未采用水嘴出水量符合现行节水认证标准的二级及以上节水器具。", "GB 55015-2021 4.1.1"));
            list.Add(new KnowledgeItem("KB119", "给排水", "雨水与污水管道混接", "建筑阳台洗衣机排水管道接入雨水立管，未设置独立的生活污水收集及防返水地漏系统。", "GB 55020-2021 4.1.3"));
            list.Add(new KnowledgeItem("KB120", "给排水", "地下集水井提升泵未设备用泵", "地下室污废水集水坑潜污泵未按一用一备原则配置，重要场所未配备应急备用自启动功能。", "GB 50015-2019 4.8.4"));
            list.Add(new KnowledgeItem("KB121", "给排水", "给水管道穿沉降缝未设挠性接头", "给排水管道穿越建筑变形缝、沉降缝处未设置橡胶挠性软接管或金属波纹补偿器。", "GB 50015-2019 3.6.11"));
            list.Add(new KnowledgeItem("KB122", "给排水", "灭火器选型配置等级不满足", "配电间、发电机房未配置适用于电气火灾的E类磷酸铵盐干粉灭火器，保护距离超标。", "GB 50140-2005 4.2.1"));
            list.Add(new KnowledgeItem("KB123", "给排水", "气体灭火系统防护区泄压口缺失", "采用七氟丙烷或IG541气体灭火系统的防护区未设置专用泄压口，且泄压口位置未处于净高2/3以上。", "GB 50370-2005 3.2.7"));
            list.Add(new KnowledgeItem("KB124", "给排水", "消防软管卷盘配置遗漏", "高层公共建筑、大型商场及人员密集场所室内消火栓箱内未同步配置消防软管卷盘或轻便水龙。", "GB 50974-2014 7.4.2"));
            list.Add(new KnowledgeItem("KB125", "给排水", "倒流防止器排水口未设间接排水", "倒流防止器泄水阀排水口直接与排水管道密闭连接，存在污水倒灌二次污染饮用水风险。", "GB 55020-2021 3.1.6"));
            list.Add(new KnowledgeItem("KB126", "给排水", "排水塑料立管未设阻火圈", "高层建筑排水塑料管穿楼板及防火墙处未设置阻火圈或防火套管，火灾时无法阻止烟火蔓延。", "GB 50015-2019 4.4.15"));
            list.Add(new KnowledgeItem("KB127", "给排水", "屋面雨水斗设置数量不足", "平屋面每个汇水面积分区内雨水斗设置数量少于2个，且天沟过长未考虑溢流排放设计。", "GB 50015-2019 5.3.3"));
            list.Add(new KnowledgeItem("KB128", "给排水", "热水供应系统循环回水短路", "集中热水供应系统干管及立管循环管道阻力不平衡，未设恒温平衡阀导致局部管段水温过低。", "GB 50015-2019 6.4.8"));
            list.Add(new KnowledgeItem("KB129", "给排水", "太阳能热水系统防过热防冻缺失", "太阳能集热器循环系统未设计膨胀泄压、防过热空晒保护及寒冷季节管道电伴热防冻措施。", "GB 55015-2021 5.2.2"));
            list.Add(new KnowledgeItem("KB130", "给排水", "给水塑料管道受热膨胀未设补偿", "超长塑料给水干管未考虑热膨胀线性伸缩量，未设置自由臂折角自然补偿或伸缩节。", "GB 50015-2019 3.6.8"));
            list.Add(new KnowledgeItem("KB131", "给排水", "餐饮废水未设隔油池直排", "商业餐饮厨房含油废水未设置油水分离器或隔油池隔油截污，直接排入室外污水管网造成堵塞。", "GB 55020-2021 4.2.5"));
            list.Add(new KnowledgeItem("KB132", "给排水", "医院污水未设消毒处理排放", "传染病及综合性医院医疗污废水未设消毒接触池消毒处理即排入市政下水道，违背卫生防疫标准。", "GB 55020-2021 4.2.8"));
            list.Add(new KnowledgeItem("KB133", "给排水", "消火栓减压孔板前后压力未标", "消火栓栓口出水动压大于0.50MPa处未设置减压孔板或减压稳压消火栓，静水压力超标。", "GB 50974-2014 7.4.12"));
            list.Add(new KnowledgeItem("KB134", "给排水", "消防稳压泵启停压力设定不符", "消防稳压设施高位稳压罐气压水容积偏小，稳压泵启停压力及联动启动主泵压力差值过小频启。", "GB 50974-2014 5.3.3"));
            list.Add(new KnowledgeItem("KB135", "给排水", "消防水泵房防水淹保护措施缺失", "地下消防水泵房室内地面未设排水沟集水坑，门槛未设挡水槛且出入口未直通安全出口。", "GB 50974-2014 5.5.12"));
            list.Add(new KnowledgeItem("KB136", "给排水", "消防水池取水口吸水高度超标", "室外消防水池供消防车取水的取水口，水池最低有效水位至地面的吸水吸程高度大于6.0m。", "GB 50974-2014 4.3.7"));
            list.Add(new KnowledgeItem("KB137", "给排水", "管道井内冷热水管间距不足", "管道井内给水立管与热水立管平行敷设净间距小于100mm，冷水管道受热烘烤影响水温与防结露。", "GB 50015-2019 3.6.5"));
            list.Add(new KnowledgeItem("KB138", "给排水", "化粪池距建筑物外墙净距不足", "室外化粪池外壁距建筑物外墙开窗洞口及地下室净距小于5m，产生异味泛溢及基础下沉隐患。", "GB 50015-2019 4.9.4"));
            list.Add(new KnowledgeItem("KB139", "给排水", "排水铸铁管与塑料管混接未过渡", "排水立管底部转向横干管未按规定采用柔性抗震铸铁管或加强型管材，水锤易破裂。", "GB 50015-2019 4.4.13"));
            list.Add(new KnowledgeItem("KB140", "给排水", "雨水虹吸系统悬吊管坡度标注错误", "建筑屋面虹吸式雨水管道悬吊管未保持水平零坡度无缝安装，标高混乱影响负压虹吸气水分离。", "GB 50015-2019 5.3.11"));
            list.Add(new KnowledgeItem("KB141", "给排水", "空调冷凝水管未设存水弯直排", "风机盘管空调冷凝水排水管直接排入生活污水立管且未设存水弯，污水臭气倒灌污染室内空气。", "GB 50736-2012 9.1.5"));
            list.Add(new KnowledgeItem("KB142", "给排水", "给排水抗震支吊架设计说明遗漏", "给水排水抗震设防烈度6度以上管径大于DN65管道未按规范设置侧向及纵向抗震支吊架。", "GB 50981-2014 3.1.2"));
            list.Add(new KnowledgeItem("KB143", "给排水", "直饮水循环回水管网死水段超标", "高品质饮用净水管网死水段长度大于2倍管径，循环回水周期过长导致微生物在死管段滋生。", "GB 55020-2021 3.1.8"));
            list.Add(new KnowledgeItem("KB144", "给排水", "无负压供水设备吸入口负压保护", "无负压（管网叠压）供水设备直接从市政供水管网抽水时未设防负压倒流消除器及停泵联锁。", "GB 55020-2021 3.2.1"));
            list.Add(new KnowledgeItem("KB145", "给排水", "中水管道与生活饮用水管道混错接", "建筑中水供水管道外壁未按规定涂刷浅绿色标志，中水取水龙头未设置防误饮带锁装置。", "GB 50336-2018 8.1.1"));
            list.Add(new KnowledgeItem("KB146", "给排水", "埋地生活给水管与排水管间距不足", "埋地给水管道与污水管道交叉时，给水管未布置在污水管上方，垂直净间距小于0.15m。", "GB 50015-2019 3.6.14"));
            list.Add(new KnowledgeItem("KB147", "给排水", "地漏水封有效深度不足50mm", "卫生间及洗衣机地漏未采用水封高度不小于50mm的构造地漏，水封极易干涸泛臭返菌。", "GB 55020-2021 4.1.4"));
            list.Add(new KnowledgeItem("KB148", "给排水", "预作用及干式喷水系统充水时间超标", "干式系统充水时间超过1min，预作用系统充水时间超过2min，未保证火灾初期喷水控火时效。", "GB 50084-2017 8.0.11"));
            list.Add(new KnowledgeItem("KB149", "给排水", "消防水泵启动控制柜非变频直接启", "消防水泵控制柜未采用工频直接启动或星三角/软启动方式，严禁在火灾工况下变频调速控制运行。", "GB 50974-2014 11.0.14"));
            list.Add(new KnowledgeItem("KB150", "给排水", "消防给水干管管径不满足设计流量", "室内消火栓竖管管径小于DN100，或架空充水管道未形成环状管网单向受阻供水。", "GB 50974-2014 8.1.5"));
            list.Add(new KnowledgeItem("KB151", "给排水", "高压细水雾系统喷头间距超限", "开式或闭式细水雾灭火系统喷头布置间距过大，细水雾覆盖区域存在遮挡死角未全淹没。", "GB 50898-2013 3.4.3"));
            list.Add(new KnowledgeItem("KB152", "给排水", "柴油发电机储油间灭火设施缺失", "建筑物内柴油发电机房储油间未按规定配置水喷雾、泡沫或气体等自动灭火设施。", "GB 55036-2022 3.1.6"));
            list.Add(new KnowledgeItem("KB153", "给排水", "室外排水雨水截污沉砂井缺失", "海绵城市透水铺装及雨水立管排放端未设置沉砂截污井，造成下渗设施与储水模块淤积堵塞。", "GB 50014-2021 4.3.2"));
            list.Add(new KnowledgeItem("KB154", "给排水", "自喷系统水流指示器前未设信号蝶阀", "水流指示器入口前未安装带电信号反馈的专用信号阀门，导致检修误关无法远程监控报警。", "GB 50084-2017 6.3.1"));
            list.Add(new KnowledgeItem("KB155", "给排水", "屋顶试验消火栓及压力表缺失", "设有室内消火栓系统的建筑屋顶或最不利楼层未设置带有压力表的试验和检验用消火栓。", "GB 50974-2014 7.4.9"));
            list.Add(new KnowledgeItem("KB156", "给排水", "生活水箱透气孔与溢流管未设防虫网", "生活水箱通气管口、溢流管口未安装耐腐蚀防护网罩，水箱人孔盖未加锁密封防蚊虫污染。", "GB 55020-2021 3.1.3"));
            list.Add(new KnowledgeItem("KB157", "暖通", "挡烟垂壁及防烟分区超标", "防烟分区长边尺寸超标，活动挡烟垂壁储烟仓厚度及排烟口保护距离不足。", "GB 51251-2017 4.2.4"));
            list.Add(new KnowledgeItem("KB158", "暖通", "排烟风管穿防火隔墙缺少防火阀", "风管穿越防火分区处未设置公称动作温度为280℃的排烟防火阀及联动反馈接点。", "GB 51251-2017 4.4.10"));
            list.Add(new KnowledgeItem("KB159", "暖通", "建筑外窗传热系数限值超标", "外门窗传热系数K值及气密性等级未满足建筑气候分区节能强制性控制指标。", "GB 55015-2021 3.2.1"));
            list.Add(new KnowledgeItem("KB160", "暖通", "厨房燃气间排风及补风缺失", "地下或半地下燃气设备间未设置独立机械通风系统及防爆事故排风装置。", "GB 50736-2012 6.3.8"));
            list.Add(new KnowledgeItem("KB161", "暖通", "排烟风管耐火极限未满足要求", "竖向排烟管道穿越不同楼层未设置管道井，或排烟管道本体耐火极限低于规范1.00h强制要求。", "GB 51251-2017 4.4.8"));
            list.Add(new KnowledgeItem("KB162", "暖通", "机械加压送风系统送风口风速超标", "防烟楼梯间前室加压送风口出风风速大于7.0m/s，风口未采用常闭型加压送风口且无手动开启装置。", "GB 51251-2017 3.3.6"));
            list.Add(new KnowledgeItem("KB163", "暖通", "机械排烟系统补风量不足", "机械排烟系统未设置补风系统，补风风量小于排烟系统计算总排烟量的50%且补风口位置过高。", "GB 51251-2017 4.5.1"));
            list.Add(new KnowledgeItem("KB164", "暖通", "自然排烟窗开启面积不足", "防烟楼梯间及其前室自然排烟窗有效可开启面积偏小，且手动开启装置高度未处于距地面0.9m至1.5m。", "GB 51251-2017 3.2.1"));
            list.Add(new KnowledgeItem("KB165", "暖通", "地下车库通风与排烟系统共用风口设置", "通风排烟合用系统排风口位置未满足下部排风1/3、上部排风及排烟2/3的气流组织设计要求。", "GB 51251-2017 4.4.12"));
            list.Add(new KnowledgeItem("KB166", "暖通", "空调供回水水力平衡装置缺失", "空调水系统并联环路阻力差额大于15%未设置动态压差平衡阀或静态水力平衡阀，末端冷热不均。", "GB 50736-2012 8.5.8"));
            list.Add(new KnowledgeItem("KB167", "暖通", "新风系统排风能量回收装置缺失", "直流式新风机组风量大于3000m³/h且新排风温差大于8℃时，未按规定设置全热/显热能量回收装置。", "GB 55015-2021 3.3.4"));
            list.Add(new KnowledgeItem("KB168", "暖通", "风管穿越变形缝未设柔性短管", "通风与空调风管穿越建筑伸缩缝、沉降缝处未设置不燃材料制作的柔性短管补偿变形。", "GB 50736-2012 6.6.14"));
            list.Add(new KnowledgeItem("KB169", "暖通", "变风量空调系统末端消声不足", "空调机房出风主干管未设置阻抗复合型微穿孔消声器，室内背景噪声达不到设计容许标准。", "GB 50736-2012 9.2.2"));
            list.Add(new KnowledgeItem("KB170", "暖通", "冷水机组能效比COP低于现行节能限值", "电驱动冷水机组额定制冷量下制冷性能系数COP及IPLV低于现行通用规范节能限定值。", "GB 55015-2021 3.3.1"));
            list.Add(new KnowledgeItem("KB171", "暖通", "采暖系统垂直失调与温控阀缺失", "新建居住建筑室内集中供暖系统未按双管系统设计，散热器进水支管未安装恒温控制阀。", "GB 55015-2021 3.3.7"));
            list.Add(new KnowledgeItem("KB172", "暖通", "公共卫生间机械排风量不足", "无外窗公共卫生间机械排风换气次数低于10次/h，且未设计门下百叶进风或负压补风构造。", "GB 50736-2012 6.3.3"));
            list.Add(new KnowledgeItem("KB173", "暖通", "事故排风机与火灾报警及气体泄露联动缺失", "氨制冷机房、变配电室SF6机房事故排风机未设室内外双向控制开关及气体泄漏自动报警连锁。", "GB 50736-2012 6.3.9"));
            list.Add(new KnowledgeItem("KB174", "暖通", "防排烟风机未设独立机房", "排烟风机及加压送风机与通风空调风机合设机房，机房隔墙耐火极限低于2.0h且检修门未采用甲级防火门。", "GB 51251-2017 4.4.5"));
            list.Add(new KnowledgeItem("KB175", "暖通", "风管穿防火墙处防火阀距墙过远", "70℃防火阀距防火墙或楼板表面距离大于200mm，风管穿越段未采用耐火隔热材料厚层保护。", "GB 50736-2012 6.6.11"));
            list.Add(new KnowledgeItem("KB176", "暖通", "冷却塔出风与新风取风口短路", "屋顶冷却塔湿热出风口与空调新风吸入口直线距离小于10m，新风引入污染与显热回流。", "GB 50736-2012 7.2.3"));
            list.Add(new KnowledgeItem("KB177", "暖通", "风道保温材料燃烧性能不满足B1级", "室内空调风管及水管绝热保温材料燃烧性能等级低于B1级，防火隔热复合层达不到阻燃安全要求。", "GB 55015-2021 3.3.12"));
            list.Add(new KnowledgeItem("KB178", "暖通", "地下车库一氧化碳CO浓度联动监测缺失", "地下汽车库机械排风系统未设置分区分组CO浓度监测传感器及联动启停排风机控制节能系统。", "GB 50736-2012 6.3.7"));
            list.Add(new KnowledgeItem("KB179", "暖通", "洁净厂房气压梯度不合规", "不同洁净等级洁净室之间静压差小于5Pa，洁净区与非洁净区静压差小于10Pa，存在交叉污染风险。", "GB 50073-2013 4.3.1"));
            list.Add(new KnowledgeItem("KB180", "暖通", "锅炉房排烟烟囱高度及防爆门未详", "常压或有压燃气锅炉排烟烟道未设泄爆门，烟囱伸出屋面高度未达到环保和日照扩散标准。", "GB 50041-2020 4.1.8"));
            list.Add(new KnowledgeItem("KB181", "暖通", "空气调节水系统定压补水膨胀罐容积偏小", "闭式循环空调冷热水系统密闭膨胀水罐有效调节容积未按系统最大水容量及水温升膨胀量复核计算。", "GB 50736-2012 8.5.15"));
            list.Add(new KnowledgeItem("KB182", "暖通", "冷冻水管道结露防潮隔气层缺失", "敷设在吊顶内的冷水管道及冷凝水管道保温层外未包裹铝箔复合玻璃钢防潮隔汽层，局部凝露滴水。", "GB 50736-2012 8.10.3"));
            list.Add(new KnowledgeItem("KB183", "暖通", "冷库冷间进出风地坪防冻胀措施", "低温冷库地坪未设计通风管道、加热电缆或地坑循环加热层，极易发生地基土冻胀隆起破坏结构。", "GB 50072-2021 4.2.1"));
            list.Add(new KnowledgeItem("KB184", "暖通", "通风空调管道抗震支架间距超标", "防排烟风管及直径大于等于0.7m的圆形风管抗震支吊架最大纵向和侧向间距超限。", "GB 50981-2014 5.1.4"));
            list.Add(new KnowledgeItem("KB185", "暖通", "电梯机房通风换气及温控不足", "电梯机房未设置机械通风或分体空调，机房环境温度超过40℃引发变频器过热停机停梯故障。", "GB 50736-2012 6.3.14"));
            list.Add(new KnowledgeItem("KB186", "暖通", "厨房排油烟风道未设坡度及集油槽", "商业餐饮厨房水平排油烟风管坡度小于2%且坡向排油烟罩，管内积油严重且未设清洗检查孔孔门。", "GB 50736-2012 6.3.11"));
            list.Add(new KnowledgeItem("KB187", "暖通", "空气处理机组凝结水封高度不足", "空调箱风机负压段冷凝水水封高度未根据风机全压静压计算，负压导致冷凝水无法排出倒吸漏水。", "GB 50736-2012 7.3.7"));
            list.Add(new KnowledgeItem("KB188", "暖通", "防排烟风机软接头非不燃材料", "防排烟风机进出口减振软接管未采用不燃无机织物材料（如硅钛防火软接），火灾时易烧毁断裂。", "GB 51251-2017 4.4.7"));
            list.Add(new KnowledgeItem("KB189", "暖通", "大空间公共建筑分层空调气流组织混乱", "展览馆、体育馆等大跨大空间建筑未采用喷口送风或侧送下回分层空调气流组织，能源浪费严重。", "GB 50736-2012 7.4.5"));
            list.Add(new KnowledgeItem("KB190", "暖通", "多联机VRV空调系统配管等效长度超标", "变制冷剂流量VRV系统室内外机单程配管等效长度及内外机垂直高差超出厂家技术设计极限制约。", "GB 50736-2012 7.3.12"));
            list.Add(new KnowledgeItem("KB191", "暖通", "燃气机房防爆事故排风系统百叶防雨", "燃气锅炉房防爆事故排风百叶风口未设电动防雨防鸟百叶，冬季冷风倒灌导致水管冻裂。", "GB 50041-2020 15.3.3"));
            list.Add(new KnowledgeItem("KB192", "暖通", "公共建筑体形系数超标未权衡判断", "建筑体形系数大于节能限值，且围护结构热工性能参数未按国家规定开展节能综合权衡计算。", "GB 55015-2021 3.1.2"));
            list.Add(new KnowledgeItem("KB193", "暖通", "空调冷凝水立管未按重力流设检查口", "超高层建筑空调冷凝水镀锌钢管或PVC立管每隔若干层未设检查清扫口，堵塞后无法疏通。", "GB 50736-2012 9.1.8"));
            list.Add(new KnowledgeItem("KB194", "暖通", "建筑排烟口未设防止人员触及保护网", "侧墙式常闭排烟口距地面安装高度低于1.8m时未设置安全防触碰护网和防误触安全罩。", "GB 51251-2017 4.4.14"));
            list.Add(new KnowledgeItem("KB195", "暖通", "加压送风机吸风口与排烟口水平净距不足", "屋顶机械加压送风机进风口与机械排烟系统出风口水平距离小于20m，未设置防止吸入烟气隔断措施。", "GB 51251-2017 3.3.5"));
            list.Add(new KnowledgeItem("KB196", "暖通", "变风量空调系统最小新风量保障不足", "VAV变风量末端关小变频运行时，总新风比未设总管压力总风量联锁控制导致新风量低于卫生标准。", "GB 50736-2012 7.1.6"));
            list.Add(new KnowledgeItem("KB197", "暖通", "柴油发电机房排烟排热风量计算不足", "地下柴油发电机房排风量未计入柴油机自身辐射热及发电机冷却散热量，导致机组高温报警熄火。", "GB 50736-2012 6.3.12"));
            list.Add(new KnowledgeItem("KB198", "暖通", "暖通空调循环水泵水头过大扬程富裕", "冷热水循环泵设计扬程过度放大安全裕量导致水泵工作点偏离高效区，发生电机过载水锤震颤。", "GB 55015-2021 3.3.3"));
            list.Add(new KnowledgeItem("KB199", "暖通", "机房内减振吊架选型刚度不匹配", "空调机房管道弹簧减振吊架固有频率与设备转速转频接近，引发管道共振与声桥传振扰民。", "GB 50736-2012 9.3.4"));
            list.Add(new KnowledgeItem("KB200", "暖通", "防排烟联动风阀未设手动复位按钮", "防火阀、排烟防火阀安装位置过高，未将手动操作机构拉索延长引至距地1.5m易操作部位。", "GB 51251-2017 5.2.3"));
            list.Add(new KnowledgeItem("KB201", "暖通", "辐射供暖供冷地板面层伸缩缝未设", "低温热水地面辐射采暖地面面积超过30㎡或长边超过6m时，未按规定设置间距不大于6m的膨胀伸缩缝。", "GB 50736-2012 5.4.11"));
            list.Add(new KnowledgeItem("KB202", "暖通", "风机盘管回风箱与空气过滤器缺失", "客房或办公室暗装风机盘管未配回风箱及初效尼龙网过滤器，积尘覆满表冷器引发换热衰减发霉。", "GB 50736-2012 7.3.3"));
            list.Add(new KnowledgeItem("KB203", "暖通", "通风机房与人员房间隔音降噪不足", "空调机房隔壁即为会议室或病房，机房隔墙未采用双层轻钢龙骨填岩棉隔声墙结构，隔声量不足50dB。", "GB 55016-2021 5.2.1"));
            list.Add(new KnowledgeItem("KB204", "暖通", "防排烟风管法兰垫片材质耐火不符", "防排烟系统风管法兰垫片采用普通橡胶板或发泡塑料，火灾高温下熔化自燃导致严重漏烟。", "GB 51251-2017 6.3.2"));
            list.Add(new KnowledgeItem("KB205", "暖通", "屋顶太阳能热水与空气源热泵系统互补控制", "空气能热泵作为辅助热源时未设置基于环境温度和太阳能水箱温差的自动梯级启闭控制逻辑。", "GB 55015-2021 5.2.4"));
            list.Add(new KnowledgeItem("KB206", "暖通", "公共建筑集中空调空气净化装置缺失", "人员聚集的公共建筑集中空调送风系统未按规范安装中效及以上颗粒物PM2.5静电净化过滤模块。", "GB 55016-2021 3.2.4"));
            list.Add(new KnowledgeItem("KB207", "暖通", "排烟系统风机全压计算漏计消声器及风阀阻力", "排烟风机选型全压未包含管网最不利阻力损失、排烟防火阀局部阻力及出口防虫百叶迎面阻力。", "GB 51251-2017 4.4.2"));
            list.Add(new KnowledgeItem("KB208", "暖通", "地下室潮湿区域新风除湿机组未设", "南方地下商场及车库未配置独立新风冷冻除湿机组，梅雨季结露凝水导致地面打滑及设备短路。", "GB 50736-2012 7.1.8"));
            list.Add(new KnowledgeItem("KB209", "电气", "变配电室未设挡水门槛", "变配电所、控制室地面未高于室外地坪，门口未设高度不低于100mm的防水挡水台。", "GB 50053-2013 6.1.8"));
            list.Add(new KnowledgeItem("KB210", "电气", "消防负荷未实现末端自动切换", "消防水泵、防排烟风机及消防电梯配电箱未在最末一级配电箱处设置双电源自动切换。", "GB 55024-2022 4.5.1"));
            list.Add(new KnowledgeItem("KB211", "电气", "应急照明地面水平最低照度不足", "疏散走道、人员密集场所及避难层地面应急照明水平照度未达到规范强制标准。", "GB 51348-2019 13.7.5"));
            list.Add(new KnowledgeItem("KB212", "电气", "配电间管洞封堵未标注", "线缆桥架穿楼板及防火墙处未标注防火泥及耐火隔板封堵等级要求。", "GB 55024-2022 4.3.2"));
            list.Add(new KnowledgeItem("KB213", "电气", "一级负荷未采用双重电源供电", "一级负荷及特级负荷未由两个独立电源供电，发生电力故障时无法满足连续供电可靠性。", "GB 55024-2022 4.1.2"));
            list.Add(new KnowledgeItem("KB214", "电气", "变配电所上方设置厕所或浴室", "变配电室正上方或正下方布置有卫生间、浴室及其他产生积水潮湿的房间，存在漏水短路隐患。", "GB 50053-2013 2.0.2"));
            list.Add(new KnowledgeItem("KB215", "电气", "电缆桥架穿越防火分区未设阻火隔断", "强弱电金属线槽及电缆桥架穿越防火分区隔墙处，内部电缆未做防火枕及膨胀型有机防火堵料封堵。", "GB 55024-2022 4.3.3"));
            list.Add(new KnowledgeItem("KB216", "电气", "柴油发电机组自启动并网时间超标", "应急柴油发电机组在主用市电中断后未在15秒内完成自启动、升压、合闸及带载运行。", "GB 51348-2019 9.1.4"));
            list.Add(new KnowledgeItem("KB217", "电气", "接地干线与防雷引下线截面不足", "建筑物防雷引下线圆钢直径小于10mm或扁钢截面小于80mm²，柱内主筋引下未可靠焊接闭合。", "GB 50057-2010 5.2.2"));
            list.Add(new KnowledgeItem("KB218", "电气", "总等电位联结MEB设置遗漏", "建筑物电源进线配电箱处、进出金属管线、建筑金属构件未做总等电位MEB端子板联结。", "GB 55024-2022 5.2.1"));
            list.Add(new KnowledgeItem("KB219", "电气", "卫生间局部等电位联结LEB缺失", "装有洗浴设施的卫生间未设置局部等电位联结箱LEB，金属管道、地漏及插座接地极未联结。", "GB 51348-2019 12.6.4"));
            list.Add(new KnowledgeItem("KB220", "电气", "低压配电回路电缆截面载流量未校核", "电缆截面仅按计算电流选择，未按电缆多根并列敷设校正系数、环境温度修正及持续短路热稳定校核。", "GB 50217-2018 3.6.2"));
            list.Add(new KnowledgeItem("KB221", "电气", "低压断路器级联选择性保护缺失", "上下级低压断路器额定电流及长延时短延时瞬动动作特性未配合，发生故障时引发大面积越级跳闸。", "GB 50054-2011 6.1.2"));
            list.Add(new KnowledgeItem("KB222", "电气", "消防配电线路未采用耐火线缆", "消防设备供电配电线路穿暗管未采用阻燃耐火线缆，明敷金属封闭线槽内未采用B1级燃烧耐火电缆。", "GB 55024-2022 4.5.3"));
            list.Add(new KnowledgeItem("KB223", "电气", "火灾自动报警系统探测器保护半径超限", "感烟探测器在梁高大于200mm顶棚布置时未考虑梁隔断影响，保护半径及保护面积超出规范要求。", "GB 50116-2013 6.2.2"));
            list.Add(new KnowledgeItem("KB224", "电气", "手动火灾报警按钮保护距离过大", "防火分区内任何位置到最邻近的手动火灾报警按钮步行距离大于30m，安装高度偏离1.3m至1.5m。", "GB 50116-2013 6.3.1"));
            list.Add(new KnowledgeItem("KB225", "电气", "消防联动控制中心未设直通室外安全出口", "消防控制室设置在首层时未设直通室外的安全出口，设置在地下层时离安全出口疏散距离过远。", "GB 50116-2013 3.4.8"));
            list.Add(new KnowledgeItem("KB226", "电气", "消防应急广播扬声器声压级不足", "走道及公共场所扬声器额定功率小于3W，声压级在环境噪声最高处未达到高于环境背景噪声15dB。", "GB 50116-2013 6.6.1"));
            list.Add(new KnowledgeItem("KB227", "电气", "防火门监控系统门磁开关与释放器缺失", "常开防火门未设置具有电动释放功能的闭门器与门磁开关，常闭防火门未设门磁状态监控器。", "GB 50116-2013 6.8.2"));
            list.Add(new KnowledgeItem("KB228", "电气", "电气火灾监控系统剩余电流互感器漏设", "三相低压总进线处未设置剩余电流式电气火灾监控探测器，报警电流设定值未满足300mA至500mA标准。", "GB 50116-2013 9.2.1"));
            list.Add(new KnowledgeItem("KB229", "电气", "室外路灯供电回路未装剩余电流保护RCD", "室外照明及景观照明回路未配置动作电流不大于30mA的剩余电流动作保护器，存在雨天触电隐患。", "GB 50054-2011 5.2.10"));
            list.Add(new KnowledgeItem("KB230", "电气", "地下汽车库照明节能分区控制缺失", "地下车库照明回路未按行车道与停车位分区分回路设计，未采用雷达感应微波探测智能照明控制。", "GB 55015-2021 3.4.1"));
            list.Add(new KnowledgeItem("KB231", "电气", "照明功率密度LPD值超出国家节能标准", "办公室、商业展厅照明计算功率密度LPD值超过现行建筑照明标准强制性目标值要求。", "GB 55015-2021 3.4.2"));
            list.Add(new KnowledgeItem("KB232", "电气", "屋面避难层接闪网网格尺寸超标", "一类或二类防雷建筑物屋顶接闪网网格尺寸超出10m×10m或12m×8m标准，避雷带未跨越女儿墙敷设。", "GB 50057-2010 4.3.1"));
            list.Add(new KnowledgeItem("KB233", "电气", "浪涌保护器SPD级联配合及后备保护缺失", "总配电箱进线端SPD与分配电箱SPD能量配合不协调，未串接专用熔断器或断路器防止老化起火。", "GB 50057-2010 4.3.8"));
            list.Add(new KnowledgeItem("KB234", "电气", "母线槽垂直穿楼板未做防水台", "封闭母线槽垂直穿越楼板处未浇筑高度不低于50mm的混凝土防水反坎，地面清洗易倒灌烧毁母排。", "GB 51348-2019 7.6.8"));
            list.Add(new KnowledgeItem("KB235", "电气", "变压器中性点接地与PE保护线混接", "TN-S系统变压器低压侧中性点引出后N线与PE线在进线柜后再次混接搭接，导致漏电误跳闸。", "GB 55024-2022 5.1.3"));
            list.Add(new KnowledgeItem("KB236", "电气", "弱电机房防静电地板及环形接地未设", "数据网络中心机房、消防安防中控室未沿墙敷设40×4紫铜环形接地排及防静电地板泄漏引线。", "GB 50314-2015 15.2.4"));
            list.Add(new KnowledgeItem("KB237", "电气", "电缆井内强弱电电缆无间距混敷", "强电高压/低压电缆与网络通信光缆同线槽或紧贴敷设，未保证300mm空间净距引发严重电磁干扰。", "GB/T 50311-2016 7.0.4"));
            list.Add(new KnowledgeItem("KB238", "电气", "厨房卫生间插座未采用防溅型及漏保", "住宅卫生间潮湿区域插座未采用防护等级IP54防溅盖板，且未设额定漏电动作电流30mA保护回路。", "GB 51348-2019 8.1.8"));
            list.Add(new KnowledgeItem("KB239", "电气", "消防水泵房双电源箱未采用机械联锁", "消防水泵双电源自动转换开关ATS未采用PC级或具备机械电气双重联锁开关，火灾时易弧光短路。", "GB 51348-2019 13.7.8"));
            list.Add(new KnowledgeItem("KB240", "电气", "消防风机控制箱缺少手自动状态远程反馈", "防排烟风机配电现场控制箱手动/自动转换开关触点信号未引回消防控制中心主机进行状态监视。", "GB 50116-2013 4.5.3"));
            list.Add(new KnowledgeItem("KB241", "电气", "变电所低压电容器无功补偿自动投切", "变电所低压配电未设功率因数自动补偿电容器组，自然功率因数低于0.90且未配置抗谐波电抗器。", "GB 50053-2013 3.3.1"));
            list.Add(new KnowledgeItem("KB242", "电气", "UPS不间断电源电池室未设防爆通风", "大容量铅酸或锂电池UPS机房未设置独立防爆排风机及氢气浓度监测报警，引发化学气体爆燃危险。", "GB 51348-2019 9.3.6"));
            list.Add(new KnowledgeItem("KB243", "电气", "金属给排水管道与桥架未做跨接接地", "跨越建筑物伸缩缝处的金属桥架两端未采用截面不小于6mm²编织软铜线跨接连接保持电气贯通。", "GB 51348-2019 12.3.8"));
            list.Add(new KnowledgeItem("KB244", "电气", "太阳能光伏电站直流侧逆变器隔离关断", "屋顶分布式光伏系统直流侧组件汇流箱处未设置带负载直流隔离开关及快速关断断路器组件。", "GB 55015-2021 5.1.4"));
            list.Add(new KnowledgeItem("KB245", "电气", "高层建筑竖向电缆防滑跌防拉断支撑", "竖向强电电缆井内长距离大截面单芯铜电缆每隔1.5m至2.0m未按规定采用绝缘电缆夹具可靠固定。", "GB 50217-2018 6.1.7"));
            list.Add(new KnowledgeItem("KB246", "电气", "配电房出入门开启方向与防火门等级", "高低压配电室通向走道的门未采用甲级防火门，且门未向疏散方向推开或未设推闩锁具。", "GB 50053-2013 6.1.3"));
            list.Add(new KnowledgeItem("KB247", "电气", "防雷接地电阻设计目标值未标注", "总说明及接地平面图中未明确防雷共用接地系统的综合接地电阻不得大于1.0Ω的设计技术限值。", "GB 50057-2010 4.1.1"));
            list.Add(new KnowledgeItem("KB248", "电气", "充电桩配电箱电能计量与消防切断", "新能源汽车充电桩配电箱未配置电能计量装置及火灾工况下非消防电源远程分励脱扣自动切断器。", "GB 51348-2019 9.6.2"));
            list.Add(new KnowledgeItem("KB249", "电气", "电缆桥架弯通转弯半径小于电缆外径允许值", "大截面高压交联聚乙烯电力电缆桥架水平垂直转弯处弯通弯曲半径小于电缆外径的15倍，挤压绝缘。", "GB 50217-2018 6.1.4"));
            list.Add(new KnowledgeItem("KB250", "电气", "可燃气体探测报警系统与切断阀联动缺失", "商业用气厨房燃气泄漏报警探头未与进气管道紧急切断电磁阀及防爆防烟排风机实现安全联动。", "GB 50116-2013 7.2.2"));
            list.Add(new KnowledgeItem("KB251", "电气", "电气竖井内插座照明检修回路缺失", "高层公共建筑弱电电缆竖井内未设计检修专用单相三孔220V电源插座和36V安全照明检修灯具。", "GB 51348-2019 7.6.11"));
            list.Add(new KnowledgeItem("KB252", "电气", "疏散指示标志灯间距与安装高度不符", "安全疏散指示标志灯在走道墙面安装间距大于20m，底边距地高度大于1.0m，遮挡逃生视线。", "GB 51348-2019 13.7.12"));
            list.Add(new KnowledgeItem("KB253", "电气", "屋顶风机防雨配电箱防护等级不足IP54", "安装在室外屋顶平台上的排烟加压风机控制箱及检修隔离开关未采用IP55/IP65户外防水防尘箱体。", "GB 51348-2019 11.2.6"));
            list.Add(new KnowledgeItem("KB254", "电气", "电梯轿厢与井道照明变压器安全电压", "电梯井道检修照明及机坑照明未采用36V及以下安全特低电压SELV供电，存在触电致命隐患。", "GB 51348-2019 10.3.4"));
            list.Add(new KnowledgeItem("KB255", "电气", "配电干线电压降计算超出允许限值", "变电所低压配电干线至最末端动力配电箱供电距离过长，电压降大于5%导致电机起动转矩不足。", "GB 50054-2011 3.2.4"));
            list.Add(new KnowledgeItem("KB256", "电气", "柴油发电机储油罐防静电及接地缺失", "发电机机房日用油箱及室外地下储油罐注油管道口未设置防静电接地夹与消除静电导电铜排。", "GB 50057-2010 4.5.3"));
            list.Add(new KnowledgeItem("KB257", "电气", "室外监控摄像机防雷防过电压未设", "安装在立杆或室外高处的安防监控网络摄像机网线及电源前端未安装二合一信号电源浪涌保护器。", "GB 50343-2012 5.4.3"));
            list.Add(new KnowledgeItem("KB258", "电气", "消防应急照明集中电源控制箱超容", "单台应急照明集中电源额定输出功率超标，配接应急标志灯具及照明灯具总数量超过点位限制。", "GB 51348-2019 13.7.7"));
            list.Add(new KnowledgeItem("KB259", "电气", "屋面金属管道及风管外壳未做防雷等电位", "突出屋面的金属排风风管、水箱及空调外机机壳未与避雷带可靠搭接两处以上形成防雷等电位。", "GB 50057-2010 4.5.1"));
            list.Add(new KnowledgeItem("KB260", "电气", "地下室潮湿配电箱未配置防凝露加热器", "南方多雨地区地下泵房配电箱内未安装带温湿度自动控制器的硅橡胶除湿加热器，引发爬电击穿。", "GB 50054-2011 7.1.3"));
            list.Add(new KnowledgeItem("KB261", "通用", "定位轴线编号遗漏或标注不清", "局部加建或核心筒区域缺少轴线定位编号，总尺寸与分尺寸链闭合存在偏差。", "GB/T 50104-2010 4.2.1"));
            list.Add(new KnowledgeItem("KB262", "通用", "图例符号引出线重叠混淆", "引出线相互交叉或遮挡文字标注，图元图层与线型不符合统一制图规范。", "GB/T 50001-2017 11.1.2"));
            list.Add(new KnowledgeItem("KB263", "通用", "标高标注基准基面不明确", "结构层标高与建筑完成面标高混淆未作文字区分说明，坡向箭头缺少坡度标注。", "GB/T 50104-2010 4.3.2"));
            list.Add(new KnowledgeItem("KB264", "通用", "图纸版本与修改标记缺失", "重大变更部位未标记图纸修改版次编号及云线批注审查标识。", "GB/T 50001-2017 14.1.1"));
            list.Add(new KnowledgeItem("KB265", "通用", "剖切符号位置与方向指示错误", "剖面图剖切符号位置线未贯穿剖切平面，投射方向线与剖面图视向方向颠倒矛盾。", "GB/T 50001-2017 7.1.2"));
            list.Add(new KnowledgeItem("KB266", "通用", "详图索引符号与被索引图纸不对应", "平面图中索引圈内详图编号或图纸编号为空，或被索引节点图纸被删除未同步更新。", "GB/T 50001-2017 7.2.1"));
            list.Add(new KnowledgeItem("KB267", "通用", "平面图与立面图窗洞定位尺寸矛盾", "建筑平面图所标门窗洞口净宽度与立面图、门窗表对应洞口尺寸出现不一致偏差。", "GB/T 50104-2010 5.1.3"));
            list.Add(new KnowledgeItem("KB268", "通用", "总平面图坐标系统及高程系统未注明", "总图未说明绝对坐标系（如国家2000坐标）与相对坐标关系，未注明黄海高程换算基准。", "GB/T 50103-2010 2.4.1"));
            list.Add(new KnowledgeItem("KB269", "通用", "总图建筑控制线与用地红线退让不足", "建筑物外墙最外凸出构件侵入用地红线或退绿线、退道路红线距离不满足规划退线指标。", "GB/T 50103-2010 3.1.2"));
            list.Add(new KnowledgeItem("KB270", "通用", "指北针或风玫瑰图绘制遗漏", "总平面图、首层建筑平面图及绿化景观平面图中未按规范要求绘制指北针或风玫瑰图。", "GB/T 50001-2017 8.0.1"));
            list.Add(new KnowledgeItem("KB271", "通用", "图纸比例与图幅尺寸选用不规范", "同一图幅内采用多比例绘制且未在图名旁单独标明比例，线型比例因子缩放失真。", "GB/T 50001-2017 4.1.1"));
            list.Add(new KnowledgeItem("KB272", "通用", "图层命名不符合工程制图统一标准", "图元未按专业图层规范分类归层，随意使用0图层或自定义未受控图层绘制主要受力构件。", "GB/T 50001-2017 3.2.1"));
            list.Add(new KnowledgeItem("KB273", "通用", "文字字体样式不满足出图打印要求", "采用非标准字体或形文件（SHX）导致图纸拷贝后字体乱码显示为问号，打印线宽过细。", "GB/T 50001-2017 5.1.1"));
            list.Add(new KnowledgeItem("KB274", "通用", "尺寸起止符号及标注界线超标", "尺寸界线超出尺寸线长度不足2mm至3mm，箭头或45度短划斜线符号大小比例失调。", "GB/T 50001-2017 10.2.1"));
            list.Add(new KnowledgeItem("KB275", "通用", "对称符号及连接符号标注不合规", "仅画出一半的对称构件未在对称中心线上画出对称符号（两对平行细线），图纸表意不清。", "GB/T 50001-2017 7.4.1"));
            list.Add(new KnowledgeItem("KB276", "通用", "引出线共用或多层构造引出顺序颠倒", "多层建筑构造（如屋面、外墙）多层引出线文字说明次序与实际剖切材料层次相反。", "GB/T 50001-2017 11.2.2"));
            list.Add(new KnowledgeItem("KB277", "通用", "图纸目录与图框签名栏信息缺失", "图纸目录中图号与实际图纸图框不对应，工程设计人、校核人、审核人签字栏空白未签署。", "GB/T 50001-2017 2.3.1"));
            list.Add(new KnowledgeItem("KB278", "通用", "专业协同碰撞管线综合平面未做", "强电弱电桥架、给排水消防管与暖通防排烟大风管在走道吊顶内重叠标高冲突碰撞严重。", "GB/T 51235-2017 4.3.2"));
            list.Add(new KnowledgeItem("KB279", "通用", "结构剪力墙梁与建筑门窗洞口打架", "结构施工图梁下净高或柱边与建筑施工图门樘预留洞口重合，导致门扇无法正常开启安装。", "GB/T 50105-2010 3.1.4"));
            list.Add(new KnowledgeItem("KB280", "通用", "机电给排水立管穿结构受力主梁", "机电穿越地下室大跨度主梁未在结构图中提前标注预留套管位置，擅自现场后凿穿梁受力筋。", "GB/T 50106-2010 4.1.3"));
            list.Add(new KnowledgeItem("KB281", "通用", "建筑伸缩缝处管线未设柔性补偿说明", "跨越建筑物沉降缝、防震缝的各类工程管线在图纸中未明确设置伸缩节或柔性补偿构件。", "GB/T 50001-2017 11.3.1"));
            list.Add(new KnowledgeItem("KB282", "通用", "设计说明引用废止失效工程规范", "工程设计总说明中引用已被住房和城乡建设部废止的历史旧标准规范，未采用最新强制条文。", "GB/T 50001-2017 2.1.3"));
            list.Add(new KnowledgeItem("KB283", "通用", "图纸修改云线批注审查闭环缺失", "各版次施工图重大设计变更修改部位未通过云线标注并编号，缺乏修改原因追踪闭环表。", "GB/T 50001-2017 14.1.2"));
            list.Add(new KnowledgeItem("KB284", "通用", "施工图设计文件深度不足施工要求", "复杂节点交接处缺少大样剖面图，仅标明由现场二次深化设计，未达到施工图设计深度。", "建质[2016]247号 1.3"));
            list.Add(new KnowledgeItem("KB285", "通用", "BIM模型碰撞检测未达LOD300精度", "机电综合管线与土建模型碰撞点位未完成协调消解，模型图元几何尺寸与设计参数缺失。", "GB/T 51212-2016 5.2.2"));
            list.Add(new KnowledgeItem("KB286", "通用", "防火分区示意图在平面图中未附", "超大面积复杂公共建筑未在各层平面图旁绘制缩小的防火分区示意图和防火卷帘位置图。", "GB/T 50104-2010 5.1.8"));
            list.Add(new KnowledgeItem("KB287", "通用", "建筑抗震设防烈度及场地类别未注明", "结构及机电抗震设计说明中未注明工程所在地抗震设防烈度、设计基本地震加速度及场地类别。", "GB/T 50105-2010 2.1.2"));
            list.Add(new KnowledgeItem("KB288", "通用", "工程耐久性设计年限及安全等级未注", "设计总说明中未明确主体结构设计工作年限（50年/100年）、建筑安全等级及耐火等级分类。", "GB/T 50001-2017 2.1.2"));
            list.Add(new KnowledgeItem("KB289", "通用", "设备基础预留洞与设备样本不符", "风机、水泵、变压器等重型机电设备基础预留螺栓孔及基础台尺寸与设备订货资料不符。", "GB/T 50114-2010 3.2.1"));
            list.Add(new KnowledgeItem("KB290", "通用", "结构板厚变化处未画标高变化线", "建筑平面上卫生间、降板露台与室内地坪存在高差处，结构施工图未画出变标高虚线及配筋剖面。", "GB/T 50105-2010 4.2.3"));
            list.Add(new KnowledgeItem("KB291", "通用", "图元线宽与打印样式CTB不匹配", "平面图中粗实线、中实线、细实线线宽对比不明显，图纸输出后主要构件轮廓无法清晰识别。", "GB/T 50001-2017 4.2.2"));
            list.Add(new KnowledgeItem("KB292", "通用", "外部参照Xref路径未采用相对路径", "外部底图底板采用绝对驱动器路径，图纸跨机器移动传输后外部参照丢失显示未加载。", "GB/T 50001-2017 3.3.4"));
            list.Add(new KnowledgeItem("KB293", "通用", "天正及专业插件实体未做转图炸开", "含有第三方插件自定义图元实体的图纸交付前未转换为AutoCAD原生基础图元，导致查看丢失。", "GB/T 50001-2017 3.1.5"));
            list.Add(new KnowledgeItem("KB294", "通用", "门窗表统计数量与平面图不相符", "门窗表中统计的各型号门窗数量与各楼层平面图中实际标注门窗编号点数存在差异遗漏。", "GB/T 50104-2010 5.2.2"));
            list.Add(new KnowledgeItem("KB295", "通用", "图纸图幅未预留装订边及装订线", "图框边距未按规范留出装订边（A0-A3留25mm，其余留5mm），装订后图纸文字被遮挡裁切。", "GB/T 50001-2017 2.2.2"));
            list.Add(new KnowledgeItem("KB296", "通用", "图纸会签栏各专业签字栏目缺失", "施工图图纸边框未设多专业会签栏，建筑、结构、给排水、暖通、电气工程师未联合会签。", "GB/T 50001-2017 2.3.4"));
            list.Add(new KnowledgeItem("KB297", "通用", "剖面图室外地坪线未加粗绘制", "建筑及结构剖面图中室外自然地坪线与设计地坪线未用特粗实线绘制，图面层次感不足。", "GB/T 50104-2010 6.1.2"));
            list.Add(new KnowledgeItem("KB298", "通用", "立面图两端定位轴线未标注", "建筑外立面图两端及主要转折点未标出对应的外墙定位轴线编号，无法与平面图对照位置。", "GB/T 50104-2010 5.3.1"));
            list.Add(new KnowledgeItem("KB299", "通用", "结构构件配筋图平法标注不规范", "梁柱平法施工图原位标注或集中标注格式偏离16G101/22G101图集国家标准注写规则。", "GB/T 50105-2010 4.1.2"));
            list.Add(new KnowledgeItem("KB300", "通用", "管线平面图管径规格标注不规范", "风管标注格式（宽×高）、水管管径（DN/De）、电缆桥架标注未统一遵循专业制图标准。", "GB/T 50106-2010 3.1.2"));
            list.Add(new KnowledgeItem("KB301", "通用", "文字注释重叠或被剖面线遮挡", "图案填充（Hatch）未对文字图元设置背景屏蔽（Wipeout），文字与阴影线条重叠不可读。", "GB/T 50001-2017 5.2.3"));
            list.Add(new KnowledgeItem("KB302", "通用", "图纸重命名规则与交付标准不合", "施工图文件命名随意未包含项目编号、专业代号、图纸序号及修改版本号，归档混乱。", "GB/T 50326-2017 8.2.1"));
            list.Add(new KnowledgeItem("KB303", "通用", "预留洞口加筋详图缺失", "结构说明中未给出剪力墙、梁上开设机电洞口后补强暗梁及斜向补强钢筋的标准构造详图。", "GB/T 50105-2010 4.4.3"));
            list.Add(new KnowledgeItem("KB304", "通用", "室外散水及坡道构造详图缺失", "建筑底层散水宽度、坡度及防冻胀伸缩缝填充沥青砂浆节点构造在详图中未做明确表达。", "GB/T 50104-2010 4.4.1"));
            list.Add(new KnowledgeItem("KB305", "通用", "图纸标题与图名下画线长度不匹配", "图名下方双横线（上粗下细）长度未与图名文字长度对齐，图纸版面排版不工整规范。", "GB/T 50001-2017 2.4.2"));
            list.Add(new KnowledgeItem("KB306", "通用", "节能计算报告书与施工图指标不一致", "外墙及屋面传热系数K值、玻璃遮阳系数SC在节能计算书与施工图设计说明中数据矛盾。", "建质[2016]247号 2.1"));
            list.Add(new KnowledgeItem("KB307", "通用", "消防专篇与各专业图纸指标矛盾", "消防专篇中描述的防火分区面积、疏散走道净宽与实际施工图平面图测量数据不符。", "建质[2016]247号 3.2"));
            list.Add(new KnowledgeItem("KB308", "通用", "绿色建筑及海绵城市专篇未落实", "设计说明承诺满足绿色建筑二星标准，但透水铺装率、雨水收集回用指标在施工图中未见落地。", "建质[2016]247号 4.1"));
            list.Add(new KnowledgeItem("KB309", "通用", "屋面检修爬梯及高差踏步标注遗漏", "建筑屋面存在大于0.6m的高差处未设置牢固的检修爬梯或踏步通道，存在高空检修坠落危险。", "GB/T 50104-2010 5.4.3"));
            list.Add(new KnowledgeItem("KB310", "通用", "施工图深化修改未附设计变更单编号", "图纸局部修改但未在修改通知单和修改图纸栏注明对应的设计变更洽商单编号和发函日期。", "GB/T 50001-2017 14.2.1"));
            list.Add(new KnowledgeItem("KB311", "通用", "抗震支吊架深化设计与原图冲突", "专业抗震支架二次深化未在原机电综合管线图上复核，导致支吊架斜撑与强电桥架干涉碰撞。", "GB/T 51235-2017 5.1.3"));
            list.Add(new KnowledgeItem("KB312", "通用", "勘察报告地质土层参数未在结构图详列", "结构基础设计总说明未附勘察报告编号、各土层承载力特征值fak及场地地下水腐蚀性评价结论。", "建质[2016]247号 2.3"));

            return list;
        }
